/* ===== painéis (hospedado): Admin e Cliente ===== */
const U=window.__U||{role:'admin',name:'Admin'},ROOTD=window.__ROOT||'';
let HM=null,CL=null;
const fx=async(u,b)=>{const r=await fetch(u,b?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(b)}:{});let j={};try{j=await r.json()}catch(e){}if(!r.ok)throw Object.assign(new Error(j.error||'erro'),{status:r.status,j});return j};
const n0=v=>(+v||0).toLocaleString('pt-BR');
const dmy=d=>String(d).split('-').reverse().slice(0,2).join('/');
const surl=s=>'https://'+s.slug+'.'+ROOTD;
const GLN=(typeof GL!=='undefined'?GL:{});
function HX(v){['home','cli'].forEach(x=>{const t=document.getElementById('t-'+x);if(t)t.classList.toggle('on',v===x)});if(v==='home'||v==='cli'){$('#t-create').classList.remove('on');$('#t-dash').classList.remove('on')}if(v==='home')loadHome();if(v==='cli')loadCli()}
function chart(ser){const W=560,H=150,P=24,mx=Math.max(4,...ser.map(a=>Math.max(a.v,a.c))),bw=(W-P*2)/ser.length;let b='',l='',lb='';ser.forEach((a,i)=>{const x=P+i*bw,h=a.v/mx*(H-30);b+='<rect x="'+(x+3)+'" y="'+(H-20-h)+'" width="'+(bw-6)+'" height="'+Math.max(h,0)+'" rx="4" fill="var(--br)" opacity=".85"><title>'+dmy(a.d)+': '+a.v+' visitas, '+a.c+' cliques</title></rect>';const cy=H-20-a.c/mx*(H-30);l+=(i?'L':'M')+(x+bw/2)+' '+cy;if(i%2===0)lb+='<text x="'+(x+bw/2)+'" y="'+(H-4)+'" font-size="9" text-anchor="middle" fill="var(--mu)">'+dmy(a.d)+'</text>'});return '<div class="chs"><svg viewBox="0 0 '+W+' '+H+'" role="img" aria-label="Visitas e cliques nos últimos 14 dias"><line x1="'+P+'" x2="'+(W-P)+'" y1="'+(H-20)+'" y2="'+(H-20)+'" stroke="var(--bd)"/>'+b+'<path d="'+l+'" fill="none" stroke="#db2777" stroke-width="2.5" stroke-linejoin="round"/>'+lb+'</svg></div><div class="lgd"><span><i style="background:var(--br)"></i>Visitas</span><span><i style="background:#db2777"></i>Cliques no WhatsApp</span></div>'}
const kp=(a,b,c)=>'<div class="kp"><small>'+a+'</small><b>'+b+'</b>'+(c?'<i>'+c+'</i>':'')+'</div>';
const ctr=(c,v)=>v?Math.round(c/v*100)+'%':'—';
function sitesTbl(sites,adm){return sites.length?'<div class="tw"><table class="tbl"><tr><th>Site</th><th>Formato</th>'+(adm?'<th>Dono</th>':'')+'<th>Visitas 30d</th><th>Cliques 30d</th><th>Taxa</th><th></th></tr>'+sites.map(s=>'<tr><td><b>'+esc(s.name)+'</b><div class="mu"><a href="'+esc(surl(s))+'" target="_blank" rel="noopener">'+esc(s.slug)+'.'+esc(ROOTD)+'</a></div></td><td>'+esc(GLN[s.goal]||s.goal)+'</td>'+(adm?'<td>'+esc(s.ownerName||'—')+'</td>':'')+'<td>'+n0(s.v30)+'</td><td>'+n0(s.c30)+'</td><td>'+ctr(s.c30,s.v30)+'</td><td><div class="rowa">'+((adm?s.owner==='admin':true)?'<button class="btn sm" onclick="openSite(\''+s.id+'\')">Editar</button>':'')+'<button class="btn sm" onclick="navigator.clipboard.writeText(\''+esc(surl(s))+'\').then(()=>toast(\'Link copiado\'))">Copiar link</button><button class="btn sm" onclick="qrOpen(\''+esc(surl(s))+'\',\''+esc(s.slug)+'\')">▦ QR</button><button class="btn sm" onclick="siteDet(\''+s.id+'\')">📈 Detalhes</button><button class="btn sm" onclick="domOpen(\''+s.id+'\')">🌐 Domínio</button>'+(adm?'<button class="btn dg sm" onclick="unpubSite(\''+s.id+'\')">Despublicar</button>':'')+'</div></td></tr>').join('')+'</table></div>':'<div class="mu" style="padding:10px 0">Nenhum site publicado ainda.</div>'}
function bkTbl(b){return b.length?'<div class="tw"><table class="tbl"><tr><th>Quando</th><th>Cliente</th><th>Serviço</th><th>Site</th></tr>'+b.slice(0,10).map(x=>'<tr><td><b>'+esc(x.d.split('-').reverse().join('/'))+' '+esc(x.t)+'</b></td><td>'+esc(x.n)+'</td><td>'+esc(x.s||'—')+'</td><td>'+esc(x.siteName)+'</td></tr>').join('')+'</table></div>':'<div class="mu" style="padding:10px 0">Nenhum agendamento futuro.</div>'}
async function openSite(id){try{const r=await fx('/api/db',{op:'get',path:'sites/'+id});if(!r.exists)throw 0;const p=sane(JSON.parse(r.data.j));p.pub=1;p.pubAt=r.data.at||Date.now();const d=await fx('/api/db',{op:'all',coll:'sites'}).catch(()=>({docs:[]})),m=(d.docs||[]).find(x=>x.id===id);if(m)p.slug=m.data.slug;edit(p)}catch(e){toast('Não consegui abrir este site')}}
async function unpubSite(id){if(!confirm('Despublicar este site? O endereço sai do ar.'))return;try{await fx('/api/admin/sites/unpublish',{id});toast('Site despublicado');loadHome();if(!$('#v-cli').hidden)loadCli()}catch(e){toast('Falha ao despublicar')}}
async function loadHome(){const box=$('#hm');try{if(U.role==='admin'){const o=await fx('/api/admin/overview');HM=o;renderAdmin(o)}else{const [me,st]=await Promise.all([fx('/api/me'),fx('/api/stats')]);HM={me,st};renderClient(me,st)}loadMsgs()}catch(e){box.innerHTML='<div class="cd">Não consegui carregar o painel agora. <button class="btn sm" onclick="loadHome()">Tentar de novo</button></div>'}}
function renderClient(me,st){const t=st.totals,pl=me.plan,pc=Math.min(100,Math.round(me.usage.sites/pl.maxSites*100)),full=me.usage.sites>=pl.maxSites;
$('#hm').innerHTML='<div class="cd" style="margin-top:6px"><div style="display:flex;gap:12px;align-items:center;flex-wrap:wrap"><div style="flex:1;min-width:220px"><h2 style="margin:0">Olá, '+esc(me.name)+' 👋</h2><div class="mu">'+esc(me.email)+'</div></div><span class="pill">Plano '+esc(pl.name)+(pl.until&&!pl.expired?' · até '+new Date(pl.until).toLocaleDateString('pt-BR'):'')+'</span>'+(me.canBuy?'<a class="btn sm" href="/planos">'+(pl.expired?'Renovar plano':'Renovar / mudar de plano')+'</a>':'')+'<button class="btn pri" onclick="show(\'create\')">＋ Criar novo site</button></div><div style="margin-top:12px"><div class="mu">Sites publicados: <b>'+me.usage.sites+' de '+pl.maxSites+'</b>'+(full?' · limite do plano atingido. Fale com o suporte para ampliar.':'')+'</div><div class="bar2" style="margin-top:4px"><div style="width:'+pc+'%"></div></div></div></div>'
+(pl.expired?'<div class="ban">⏰ Seu plano <b>'+esc((pl.wanted&&{basic:'Essencial',pro:'Pro',premium:'Premium'}[pl.wanted])||'')+'</b> venceu e a conta voltou ao limite do plano Gratuito. Seus sites continuam no ar. '+(me.canBuy?'<a href="/planos">Renovar agora</a>':'Fale com o suporte para renovar.')+'</div>':(pl.until&&pl.until-Date.now()<5*864e5?'<div class="ban">⏰ Seu plano vence em '+Math.max(0,Math.ceil((pl.until-Date.now())/864e5))+' dia(s). '+(me.canBuy?'<a href="/planos">Renovar agora</a>':'')+'</div>':''))+(me.tmp?'<div class="ban">🔐 Você está usando uma senha temporária. Troque agora em <a href="#conta" onclick="document.getElementById(\'acc\').scrollIntoView({behavior:\'smooth\'});return false">Minha conta</a>.</div>':'')
+(me.trialOk?'<div class="ban">🎁 Experimente o plano <b>Pro por 7 dias</b>, grátis e sem cartão. <button class="btn pri sm" onclick="trialGo()">Ativar teste grátis</button></div>':'')+'<div class="kg">'+kp('Sites no ar',t.sites)+kp('Visitas (7 dias)',n0(t.views7),n0(t.views30)+' em 30 dias')+kp('Cliques no WhatsApp',n0(t.clicks7),n0(t.clicks30)+' em 30 dias')+kp('Taxa de clique',ctr(t.clicks30,t.views30),'cliques ÷ visitas (30d)')+kp('Agendamentos futuros',t.bookings)+'</div>'
+'<div class="hg"><div class="cd"><h3 style="margin:0 0 6px">Visitas e cliques · últimos 14 dias</h3>'+chart(st.series)+(st.capped?'<div class="mu">Mostrando os eventos mais recentes.</div>':'')+'</div><div class="cd"><h3 style="margin:0 0 6px">Próximos agendamentos</h3>'+bkTbl(st.bookings)+'</div></div>'
+'<div class="cd" style="margin-top:14px"><h3 style="margin:0 0 6px">Meus sites publicados</h3>'+sitesTbl(st.sites,false)+'<div class="mu" style="margin-top:8px">Rascunhos ficam em <a href="#" onclick="show(\'dash\');return false">Meus sites</a>. Publique para o site entrar no ar.</div></div>'
+'<div class="cd" style="margin-top:14px"><h3 style="margin:0 0 6px">📬 Mensagens, presenças e contatos</h3><div id="msgs" class="mu">Carregando…</div></div>'
+(me.ref?'<div class="cd" style="margin-top:14px"><h3 style="margin:0 0 6px">🎁 Indique e ganhe 7 dias grátis</h3><div class="mu">Quando alguém criar conta pelo seu link e assinar um plano, você ganha +7 dias.</div><div class="rowa" style="margin-top:8px"><input class="inp" readonly value="'+esc(me.ref.link)+'" style="flex:1;min-width:200px" onclick="this.select()"><button class="btn sm" onclick="navigator.clipboard.writeText(\''+esc(me.ref.link)+'\').then(()=>toast(\'Link copiado\'))">Copiar</button><a class="btn sm" target="_blank" rel="noopener" href="https://wa.me/?text='+encodeURIComponent('Crie seu site em minutos com o AutoPage e teste o plano Pro por 7 dias: '+me.ref.link)+'">Enviar no WhatsApp</a></div><div class="mu" style="margin-top:6px">'+me.ref.signups+' cadastro(s) · '+me.ref.rewards+' recompensa(s) recebida(s)</div></div>':'')
+'<div class="cd" id="acc" style="margin-top:14px"><h3 style="margin:0 0 6px">Minha conta</h3><div class="g2"><div><label class="l" style="margin-top:0">Nome</label><input class="inp" id="ac-n" value="'+esc(me.name)+'" maxlength="80"></div><div><label class="l" style="margin-top:0">E-mail</label><input class="inp" value="'+esc(me.email)+'" disabled></div></div><button class="btn sm" style="margin-top:8px" onclick="accSave(0)">Salvar nome</button><div class="g2"><div><label class="l">Senha atual</label><input class="inp" type="password" id="ac-o" autocomplete="current-password"></div><div><label class="l">Nova senha (8+ caracteres)</label><input class="inp" type="password" id="ac-p" autocomplete="new-password"></div></div><button class="btn sm" style="margin-top:8px" onclick="accSave(1)">Trocar senha</button></div>'}
async function trialGo(){try{await fx('/api/trial',{});toast('Teste de 7 dias ativado!');loadHome()}catch(e){toast(e.message||'Falha')}}
async function accSave(pw){try{if(pw)await fx('/api/account',{oldPassword:$('#ac-o').value,newPassword:$('#ac-p').value});else await fx('/api/account',{name:$('#ac-n').value});toast(pw?'Senha alterada':'Nome salvo');loadHome()}catch(e){toast(e.message||'Falha')}}
function renderAdmin(o){const k=o.kpi,t=o.totals,top=o.sites.slice().sort((a,b)=>b.v30-a.v30).slice(0,6),pc={};o.clients.forEach(c=>{pc[c.plan.name]=(pc[c.plan.name]||0)+1});
$('#hm').innerHTML='<div class="cd" style="margin-top:6px;display:flex;gap:12px;align-items:center;flex-wrap:wrap"><div style="flex:1;min-width:220px"><h2 style="margin:0">Painel do administrador 🛠️</h2><div class="mu">Visão geral de clientes, sites e resultados</div></div><button class="btn" onclick="show(\'cli\')">👥 Gerenciar clientes</button><button class="btn pri" onclick="show(\'create\')">＋ Criar site</button></div>'
+'<div class="kg">'+kp('Clientes',k.clients,k.active+' ativos · '+k.blocked+' bloqueados')+kp('Novos (30 dias)',k.new30)+kp('Sites no ar',t.sites)+kp('Visitas (7 dias)',n0(t.views7),n0(t.views30)+' em 30 dias')+kp('Cliques no WhatsApp',n0(t.clicks7),n0(t.clicks30)+' em 30 dias')+kp('Taxa de clique',ctr(t.clicks30,t.views30))+kp('Agendamentos futuros',t.bookings)+kp('Vendas (30 dias)','R$ '+(o.sales.rev30||0).toFixed(2).replace('.',','),o.sales.count30+' pedido(s) pagos · '+o.sales.pending+' aguardando')+kp('IA hoje',k.aiToday+' / '+k.aiLimit,'Banco: '+esc(k.store))+kp('E-mail',o.mail?'ativo':'desligado',o.mail?'avisos e recibos':'defina RESEND_API_KEY')+kp('Domínios próprios',o.domains||0,o.signup?'cadastro aberto':'cadastro fechado')+'</div>'
+'<div class="hg"><div class="cd"><h3 style="margin:0 0 6px">Visitas e cliques · últimos 14 dias</h3>'+chart(o.series)+'</div><div class="cd"><h3 style="margin:0 0 6px">Clientes por plano</h3>'+(Object.keys(pc).length?Object.entries(pc).map(a=>'<div style="display:flex;justify-content:space-between;padding:6px 0;border-bottom:1px solid var(--bd)"><span>'+esc(a[0])+'</span><b>'+a[1]+'</b></div>').join(''):'<div class="mu">Nenhum cliente ainda.</div>')+'<h3 style="margin:14px 0 6px">Últimos clientes</h3>'+(o.clients.slice(0,5).map(c=>'<div style="padding:5px 0"><b>'+esc(c.name)+'</b> <span class="pill '+(c.status==='active'?'ok':'er')+'">'+(c.status==='active'?'ativo':'bloqueado')+'</span><div class="mu">'+esc(c.email)+'</div></div>').join('')||'<div class="mu">—</div>')+'</div></div>'
+'<div class="hg" style="margin-top:14px"><div class="cd"><h3 style="margin:0 0 6px">Sites com mais visitas (30 dias)</h3>'+sitesTbl(top,true)+'</div><div class="cd"><h3 style="margin:0 0 6px">Próximos agendamentos</h3>'+bkTbl(o.bookings)+'</div></div>'
+'<div class="cd" style="margin-top:14px"><h3 style="margin:0 0 6px">📬 Mensagens, presenças e contatos</h3><div id="msgs" class="mu">Carregando…</div></div>'}
/* ----- Clientes (admin) ----- */
async function loadCli(){const box=$('#cl');try{const o=await fx('/api/admin/overview');CL=o;renderCli(o)}catch(e){box.innerHTML='<div class="cd">Não consegui carregar. <button class="btn sm" onclick="loadCli()">Tentar de novo</button></div>'}}
function renderCli(o){const po=Object.entries(o.plans).map(a=>'<option value="'+a[0]+'">'+esc(a[1].name)+' ('+a[1].maxSites+' site'+(a[1].maxSites>1?'s':'')+')</option>').join('');
$('#cl').innerHTML='<div class="cd" style="margin-top:6px"><h2 style="margin:0 0 4px">Novo cliente</h2><div class="mu">Gera um acesso com senha temporária. O cliente troca a senha no primeiro login.</div><div class="g2"><div><label class="l">Nome</label><input class="inp" id="nc-n" maxlength="80"></div><div><label class="l">E-mail</label><input class="inp" id="nc-e" type="email"></div></div><div class="g2"><div><label class="l">Plano</label><select class="inp" id="nc-p">'+po+'</select></div><div><label class="l">Observação (opcional)</label><input class="inp" id="nc-o" maxlength="300"></div></div><button class="btn pri" style="margin-top:10px" onclick="newCli()">Criar acesso</button><div id="nc-r"></div></div>'
+'<div class="cd" style="margin-top:14px"><h2 style="margin:0 0 4px">Vendas dos planos</h2><div class="mu">Página de venda: <code>https://app.'+esc(ROOTD)+'/planos</code> '+(o.mp?'· Mercado Pago <span class="pill ok">conectado</span>':'· Mercado Pago <span class="pill er">não conectado: defina MP_ACCESS_TOKEN no Render</span>')+'</div><div class="kg">'+Object.entries(o.plans).map(a=>'<div class="kp"><small>'+esc(a[1].name)+' · '+a[1].maxSites+' site(s)</small><input class="inp" type="number" min="0" step="0.01" id="pr-'+a[0]+'" placeholder="Preço R$ (vazio = não vender)" value="'+(o.prices[a[0]]||'')+'"></div>').join('')+'</div><div class="rowa"><button class="btn sm" onclick="savePrices()">Salvar preços</button><button class="btn sm" onclick="navigator.clipboard.writeText(\'https://app.'+esc(ROOTD)+'/planos\').then(()=>toast(\'Link copiado\'))">Copiar link de venda</button><a class="btn sm" href="/api/admin/export">⬇ Baixar backup (JSON)</a></div>'+(o.sales.recent.length?'<div class="tw" style="margin-top:10px"><table class="tbl"><tr><th>Quando</th><th>Comprador</th><th>Plano</th><th>Valor</th><th>Status</th></tr>'+o.sales.recent.map(x=>'<tr><td>'+new Date(x.at).toLocaleDateString('pt-BR')+'</td><td>'+esc(x.name)+'<div class="mu">'+esc(x.email)+'</div></td><td>'+esc((o.plans[x.plan]||{}).name||x.plan)+'</td><td>R$ '+(+x.amount).toFixed(2).replace('.',',')+'</td><td><span class="pill '+(x.status==='paid'?'ok':'')+'">'+(x.status==='paid'?'pago':'aguardando')+'</span></td></tr>').join('')+'</table></div>':'')+'</div>'
+'<div class="cd" style="margin-top:14px"><h2 style="margin:0 0 4px">Cupons de desconto</h2><div class="mu">O cliente digita o código na página de planos. O desconto vale para a compra de qualquer plano.</div><div class="g2"><div><label class="l">Código (ex.: LANCAMENTO20)</label><input class="inp" id="cu-c" maxlength="20" style="text-transform:uppercase"></div><div><label class="l">Desconto (%)</label><input class="inp" id="cu-p" type="number" min="1" max="90" value="10"></div></div><div class="g2"><div><label class="l">Limite de usos (0 = sem limite)</label><input class="inp" id="cu-m" type="number" min="0" value="0"></div><div><label class="l">Validade em dias (0 = sem prazo)</label><input class="inp" id="cu-d" type="number" min="0" value="0"></div></div><button class="btn sm" style="margin-top:8px" onclick="cupSave()">Salvar cupom</button>'+((o.coupons||[]).length?'<div class="tw" style="margin-top:10px"><table class="tbl"><tr><th>Código</th><th>Desconto</th><th>Usos</th><th>Validade</th><th></th></tr>'+o.coupons.map(c=>'<tr><td><b>'+esc(c.code)+'</b></td><td>'+c.pct+'%</td><td>'+(c.used||0)+(c.max?' / '+c.max:'')+'</td><td>'+(c.exp?new Date(c.exp).toLocaleDateString('pt-BR'):'sem prazo')+'</td><td><button class="btn dg sm" onclick="cupDel(\''+esc(c.code)+'\')">Excluir</button></td></tr>').join('')+'</table></div>':'')+'</div>'
+'<div class="cd" style="margin-top:14px"><h2 style="margin:0 0 4px">Domínios próprios</h2><div class="mu">Depois que o DNS apontar para o servidor, adicione o domínio também no Render (Settings → Custom Domains) para liberar o HTTPS.</div><div id="doms" class="tw">Carregando…</div></div>'
+'<div class="cd" style="margin-top:14px"><h2 style="margin:0 0 4px">Backups</h2><div class="mu">O app guarda os 3 últimos backups diários no banco'+(o.mail?' e envia o arquivo para o e-mail do administrador.':'. Defina RESEND_API_KEY e ADMIN_EMAIL para receber o arquivo por e-mail.')+'</div><div id="bk" class="tw">Carregando…</div></div>'
+'<div class="cd" style="margin-top:14px"><h2 style="margin:0 0 4px">Atividade recente</h2><div id="aud" class="tw">Carregando…</div></div>'
+'<div class="cd" style="margin-top:14px"><div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap"><h2 style="margin:0;flex:1">Clientes ('+o.clients.length+')</h2><input class="inp" id="cq" placeholder="Buscar por nome ou e-mail" style="max-width:260px" oninput="cliRows()"></div><div class="tw" id="crow"></div></div>'
+'<div class="cd" style="margin-top:14px"><h2 style="margin:0 0 6px">Todos os sites publicados ('+o.sites.length+')</h2>'+sitesTbl(o.sites,true)+'</div>';cliRows();loadDoms();loadBk();loadAud()}
function cliRows(){const q=($('#cq')?$('#cq').value:'').toLowerCase(),po=Object.entries(CL.plans),l=CL.clients.filter(c=>!q||(c.name+' '+c.email).toLowerCase().includes(q));$('#crow').innerHTML=l.length?'<table class="tbl"><tr><th>Cliente</th><th>Plano</th><th>Sites</th><th>Último acesso</th><th>Status</th><th></th></tr>'+l.map(c=>'<tr><td><b>'+esc(c.name)+'</b><div class="mu">'+esc(c.email)+(c.note?' · '+esc(c.note):'')+'</div></td><td><select class="inp" style="padding:4px" onchange="cliUp(\''+c.id+'\',{plan:this.value})">'+po.map(a=>'<option value="'+a[0]+'"'+(a[0]===c.plan.key?' selected':'')+'>'+esc(a[1].name)+'</option>').join('')+'</select></td><td>'+c.sites+' / '+c.plan.maxSites+' <button class="btn sm" title="Alterar limite de sites" onclick="cliMax(\''+c.id+'\','+c.plan.maxSites+')">✎</button></td><td>'+(c.lastLogin?new Date(c.lastLogin).toLocaleDateString('pt-BR'):'nunca')+(c.tmp?' <span class="pill">senha temporária</span>':'')+(c.plan.until?'<div class="mu">'+(c.plan.expired?'plano vencido em ':'plano até ')+new Date(c.plan.until).toLocaleDateString('pt-BR')+'</div>':'')+'</td><td><span class="pill '+(c.status==='active'?'ok':'er')+'">'+(c.status==='active'?'ativo':'bloqueado')+'</span></td><td><div class="rowa"><button class="btn sm" onclick="cliUp(\''+c.id+'\',{status:\''+(c.status==='active'?'blocked':'active')+'\'})">'+(c.status==='active'?'Bloquear':'Ativar')+'</button><button class="btn sm" onclick="cliPw(\''+c.id+'\',\''+esc(c.email)+'\')">Nova senha</button><button class="btn dg sm" onclick="cliDel(\''+c.id+'\')">Excluir</button></div></td></tr>').join('')+'</table>':'<div class="mu" style="padding:10px 0">Nenhum cliente encontrado.</div>'}
async function savePrices(){const pr={};Object.keys(CL.plans).forEach(k=>{const v=parseFloat($('#pr-'+k).value);if(v>0)pr[k]=v});try{await fx('/api/admin/config',{prices:pr});toast('Preços salvos');loadCli()}catch(e){toast('Falha ao salvar')}}
function credBox(email,pw,tit){const msg='Seu acesso ao AutoPage.ai\nEndereço: https://app.'+ROOTD+'\nE-mail: '+email+'\nSenha temporária: '+pw+'\nTroque a senha no primeiro acesso.';return '<div class="cr"><b>'+tit+'</b><div style="margin-top:6px">Endereço: <code>https://app.'+esc(ROOTD)+'</code><br>E-mail: <code>'+esc(email)+'</code><br>Senha temporária: <code>'+esc(pw)+'</code></div><div class="mu" style="margin:6px 0">Essa senha aparece só agora. Copie e envie ao cliente.</div><div class="rowa"><button class="btn sm" onclick="navigator.clipboard.writeText('+esc(JSON.stringify(msg)).replace(/&quot;/g,'&quot;')+').then(()=>toast(\'Acesso copiado\'))">Copiar acesso</button><a class="btn sm" target="_blank" rel="noopener" href="https://wa.me/?text='+encodeURIComponent(msg)+'">Enviar no WhatsApp</a></div></div>'}
async function newCli(){try{const r=await fx('/api/admin/clients',{name:$('#nc-n').value,email:$('#nc-e').value,plan:$('#nc-p').value,note:$('#nc-o').value});await loadCli();$('#nc-r').innerHTML=credBox(r.user.email,r.password,'✅ Cliente criado: '+esc(r.user.name))}catch(e){toast(e.message||'Falha ao criar')}}
