function modal(h){mclose();const m=document.createElement('div');m.id='mdl';m.className='mdl';m.innerHTML='<div class="mbx" role="dialog" aria-modal="true">'+h+'</div>';m.onclick=e=>{if(e.target===m)mclose()};document.body.appendChild(m)}
function mclose(){const m=document.getElementById('mdl');if(m)m.remove()}
addEventListener('keydown',e=>{if(e.key==='Escape')mclose()});
function qrPng(url,px){const q=new QRC(-1,0);q.addData(url);q.make();const n=q.getModuleCount(),m=4,sz=Math.max(3,Math.floor((px||520)/(n+2*m))),W=sz*(n+2*m),c=document.createElement('canvas');c.width=c.height=W;const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,W,W);x.fillStyle='#000';for(let r=0;r<n;r++)for(let k=0;k<n;k++)if(q.isDark(r,k))x.fillRect((k+m)*sz,(r+m)*sz,sz,sz);return c.toDataURL('image/png')}
function qrOpen(url,name){let img;try{img=qrPng(url)}catch(e){toast('Não consegui gerar o QR Code');return}window.__qr={url,img,name:name||'site'};modal('<h3 style="margin:0 0 4px">▦ QR Code do site</h3><div class="mu" style="margin-bottom:10px">Imprima em cartão, balcão ou panfleto. Quem apontar a câmera abre o site.</div><div style="text-align:center"><img src="'+img+'" alt="QR Code de '+esc(url)+'" style="width:260px;max-width:100%;border-radius:12px;background:#fff"></div><div class="mu" style="text-align:center;margin:8px 0;word-break:break-all">'+esc(url)+'</div><div class="rowa" style="justify-content:center"><a class="btn pri sm" download="qr-'+esc(name||'site')+'.png" href="'+img+'">⬇ Baixar PNG</a><button class="btn sm" onclick="qrPrint()">🖨️ Imprimir</button><button class="btn sm" onclick="navigator.clipboard.writeText(__qr.url).then(()=>toast(\'Link copiado\'))">Copiar link</button><button class="btn sm" onclick="mclose()">Fechar</button></div>')}
function qrPrint(){const f=document.createElement('iframe');f.style.cssText='position:fixed;width:0;height:0;border:0';document.body.appendChild(f);f.contentDocument.write('<body style="text-align:center;font:20px system-ui"><h2>'+esc(__qr.name)+'</h2><img src="'+__qr.img+'" style="width:340px"><p>'+esc(__qr.url)+'</p>');f.contentDocument.close();f.onload=null;setTimeout(()=>{f.contentWindow.focus();f.contentWindow.print();setTimeout(()=>f.remove(),2000)},300)}
function qrCur(){if(!(P&&P.pub&&P.slug)){toast('Publique o site primeiro');return}qrOpen('https://'+P.slug+'.'+ROOTD,P.slug)}
async function siteDet(id){modal('<div class="mu">Carregando…</div>');try{const r=await fx('/api/stats/site?id='+encodeURIComponent(id)),cl=r.days.reduce((a,x)=>a+x.c,0),vw=r.days.reduce((a,x)=>a+x.v,0);modal('<h3 style="margin:0 0 8px">📈 Detalhes do site · 30 dias</h3><div class="kg" style="margin:8px 0">'+kp('Visitantes únicos',n0(r.unique30),n0(r.unique7)+' nos últimos 7 dias')+kp('Voltaram ao site',n0(r.returning30),'mais de 1 visita')+kp('Visitas',n0(vw))+kp('Cliques',n0(cl),ctr(cl,vw)+' das visitas')+'</div>'+chart(r.days)+'<h4 style="margin:12px 0 6px">Botões e links mais clicados</h4>'+(r.links.length?r.links.map(l=>'<div style="display:flex;justify-content:space-between;padding:5px 0;border-bottom:1px solid var(--bd)"><span>'+esc(l.l)+'</span><b>'+l.c+'</b></div>').join(''):'<div class="mu">Nenhum clique ainda.</div>')+'<div style="margin-top:12px"><button class="btn sm" onclick="mclose()">Fechar</button></div>')}catch(e){modal('<div>Não consegui carregar os detalhes.</div><button class="btn sm" onclick="mclose()">Fechar</button>')}}
async function domOpen(id){modal('<div class="mu">Carregando…</div>');try{const r=await fx('/api/domains'),d=r.items.find(x=>x.site===id);window.__dsite=id;modal('<h3 style="margin:0 0 4px">🌐 Domínio próprio</h3><div class="mu">Use seu endereço, como <b>meusite.com.br</b>, em vez do endereço padrão. Disponível nos planos pagos.</div>'+(d?'<div class="cr"><b>'+esc(d.host)+'</b> '+(d.ok?'<span class="pill ok">verificado</span>':'<span class="pill">aguardando DNS</span>')+'<div class="mu" style="margin:6px 0">No painel onde você comprou o domínio, crie um registro <b>CNAME</b> apontando para <code>'+esc(r.target)+'</code> (para o domínio raiz, use o ANAME/ALIAS ou o registro A que seu provedor indicar). Depois clique em Verificar. A propagação pode levar de alguns minutos a algumas horas.</div>'+(d.ok?'<div class="mu">Para ativar o HTTPS, avise o suporte para liberar o domínio no servidor.</div>':'')+'<div class="rowa">'+(d.ok?'':'<button class="btn pri sm" onclick="domVerify(\''+esc(d.host)+'\')">Verificar DNS</button>')+'<button class="btn dg sm" onclick="domDel(\''+esc(d.host)+'\')">Remover</button></div></div>':'<label class="l">Seu domínio</label><input class="inp" id="dm-h" placeholder="meusite.com.br" maxlength="100"><div class="rowa" style="margin-top:8px"><button class="btn pri sm" onclick="domSet()">Conectar domínio</button></div>')+'<div style="margin-top:12px"><button class="btn sm" onclick="mclose()">Fechar</button></div>')}catch(e){modal('<div>Não consegui carregar.</div><button class="btn sm" onclick="mclose()">Fechar</button>')}}
async function domSet(){try{await fx('/api/domain',{site:window.__dsite,domain:$('#dm-h').value});domOpen(window.__dsite)}catch(e){toast(e.message||'Falha')}}
async function domVerify(h){try{const r=await fx('/api/domain/verify',{domain:h});toast(r.ok?'Domínio verificado!':'O DNS ainda não aponta para o servidor. Tente de novo mais tarde.');domOpen(window.__dsite)}catch(e){toast('Falha ao verificar')}}
async function domDel(h){if(!confirm('Remover este domínio?'))return;try{await fx('/api/domain/delete',{domain:h});domOpen(window.__dsite)}catch(e){toast('Falha')}}
async function loadDoms(){const b=$('#doms');if(!b)return;try{const r=await fx('/api/domains');b.innerHTML=r.items.length?'<table class="tbl"><tr><th>Domínio</th><th>Status</th><th>Ação no Render</th><th></th></tr>'+r.items.map(d=>'<tr><td><b>'+esc(d.host)+'</b></td><td><span class="pill '+(d.ok?'ok':'')+'">'+(d.ok?'DNS verificado':'aguardando DNS')+'</span></td><td class="mu">'+(d.ok?'adicionar em Custom Domains (HTTPS)':'—')+'</td><td><button class="btn dg sm" onclick="domAdm(\''+esc(d.host)+'\')">Remover</button></td></tr>').join('')+'</table>':'<div class="mu" style="padding:8px 0">Nenhum domínio próprio ainda.</div>'}catch(e){b.textContent='—'}}
