async function verOpen(){if(!P||!P.id)return;modal('<div class="mu">Carregando…</div>');try{const r=await fx('/api/versions?site='+encodeURIComponent(P.id));modal('<h3 style="margin:0 0 4px">🕘 Versões publicadas</h3><div class="mu" style="margin-bottom:8px">Cada vez que você publica, a versão anterior é guardada (últimas 6). Restaurar coloca a versão antiga no ar e abre ela no editor.</div>'+(r.items.length?r.items.map(v=>'<div class="li" style="padding:8px 0;display:flex;gap:8px;align-items:center"><div style="flex:1"><b>'+esc(v.name||'Versão')+'</b><div class="mu">'+(v.at?new Date(v.at).toLocaleString('pt-BR'):'')+' · '+v.kb+' KB</div></div><button class="btn sm" onclick="verGo(\''+esc(v.v)+'\')">Restaurar</button></div>').join(''):'<div class="mu">Ainda não há versões anteriores. Elas aparecem depois que você publicar alterações.</div>')+'<div style="margin-top:12px"><button class="btn sm" onclick="mclose()">Fechar</button></div>')}catch(e){modal('<div>Não consegui carregar as versões. Publique o site primeiro.</div><button class="btn sm" onclick="mclose()">Fechar</button>')}}
