async function loadMsgs(){const b=$('#msgs');if(!b)return;try{const r=await fx('/api/messages');b.innerHTML=r.items.length?'<div class="rowa" style="margin-bottom:8px"><a class="btn sm" href="/api/messages?csv=1">⬇ Baixar CSV ('+r.total+')</a></div><div class="tw"><table class="tbl"><tr><th>Quando</th><th>Tipo</th><th>Nome / contato</th><th>Mensagem</th><th>Site</th><th></th></tr>'+r.items.slice(0,15).map(m=>{const ph=String(m.c||'').replace(/\D/g,'');return '<tr><td>'+new Date(m.at).toLocaleDateString('pt-BR')+'</td><td>'+(MI[m.type]||m.type)+'</td><td><b>'+esc(m.n)+'</b><div class="mu">'+(ph.length>=10?'<a target="_blank" rel="noopener" href="https://wa.me/'+(ph.length<=11?'55':'')+ph+'">'+esc(m.c)+'</a>':esc(m.c||''))+'</div></td><td>'+esc(m.m||'')+(m.x?'<div class="mu">'+esc(m.x)+'</div>':'')+'</td><td>'+esc(m.siteName)+'</td><td><button class="btn dg sm" onclick="msgDel(\''+m.site+'\',\''+m.id+'\')">✕</button></td></tr>'}).join('')+'</table></div>':'Nenhuma mensagem ainda. Formulários de contato, confirmações de presença e cadastros dos seus sites aparecem aqui.'}catch(e){b.textContent='Não consegui carregar as mensagens.'}}
