function vndOrd(o){const w=waLink(o,VS.d.site.name||'');const it=o.items.map(l=>l.q+'× '+esc(l.n)+(l.v?' ('+esc(l.v)+')':'')).join(', ');
return '<div class="ord'+(o.st==='novo'?' n':'')+'"><div class="rowa" style="justify-content:space-between"><b>#'+o.no+' · '+esc(o.name||'Cliente')+'</b><span><b>'+BRL(o.total)+'</b> <small>'+new Date(o.at).toLocaleString('pt-BR',{day:'2-digit',month:'2-digit',hour:'2-digit',minute:'2-digit'})+'</small></span></div><div style="font-size:13px">'+it+'</div><small>'+(o.mode==='entrega'?'🛵 Entrega'+(o.addr?': '+esc(o.addr):''):'🏪 Retirada')+(o.pay==='online'?' · 💳 Online: '+({pago:'✅ Pago',aguardando:'⏳ Aguardando pagamento',recusado:'❌ Recusado',estornado:'↩ Estornado'}[o.pg]||''):(o.pay?' · '+esc(o.pay):''))+(o.fee?' · frete '+BRL(o.fee)+(o.ship?' ('+esc(o.ship.company+' '+o.ship.name)+', '+(o.ship.days||'?')+' dias, CEP '+esc(o.ship.cep)+')':''):'')+(o.d?' · desconto '+BRL(o.d):'')+(o.tel?' · '+esc(o.tel):'')+(o.be?' · ✉ '+esc(o.be):'')+(o.obs?' · “'+esc(o.obs)+'”':'')+'</small><div class="rowa" style="justify-content:space-between;align-items:center"><span class="st">'+Object.keys(STL).map(k=>'<button class="'+(o.st===k?'on':'')+'" '+(o.st==='cancelado'&&k!=='cancelado'?'disabled ':'')+'onclick="vndSt(\''+o.id+'\',\''+k+'\')">'+STL[k]+'</button>').join('')+'</span>'+(w?'<a class="btn sm" target="_blank" rel="noopener" href="'+w+'">💬 Avisar cliente</a>':'<small>sem WhatsApp do cliente</small>')+'</div></div>'}
function vndProd(p){return '<tr><td>'+(p.x?'<span class="pill" style="background:#fde68a;color:#78350f;font-size:10px;padding:2px 7px;border-radius:99px;font-weight:800">EXEMPLO</span> ':'')+'<input value="'+esc(p.n)+'" maxlength="80" onchange="vndUp('+p.i+',{n:this.value})"></td><td><input class="w2" value="'+String(p.p).replace('.',',')+'" inputmode="decimal" onchange="vndUp('+p.i+',{p:this.value.replace(\',\',\'.\')})"></td><td><input class="w1" value="'+(p.s===''?'':p.s)+'" inputmode="numeric" placeholder="∞" onchange="vndUp('+p.i+',{s:this.value})"></td><td><input type="checkbox" '+(p.o?'checked ':'')+'onchange="vndUp('+p.i+',{o:this.checked?1:0})" style="width:auto"></td><td><input class="w1" value="'+(p.w===''?'':p.w)+'" inputmode="numeric" placeholder="auto" onchange="vndUp('+p.i+',{w:this.value})"></td><td style="white-space:nowrap"><button class="btn sm" onclick="vndMv('+p.i+',-1)" aria-label="Subir">↑</button> <button class="btn sm" onclick="vndMv('+p.i+',1)" aria-label="Descer">↓</button> <button class="btn sm" onclick="vndDel('+p.i+')" aria-label="Excluir">🗑</button></td></tr>'}
async function vndOp(b,ok){try{await fx('/api/sales/product',Object.assign({site:VS.site},b));if(ok)toast(ok);await vndSite()}catch(e){toast(e.status===409?'Limite de 60 itens atingido':e.message==='name'?'Informe o nome':'Falha ao salvar');await vndSite()}}
const vndUp=(i,patch)=>vndOp({op:'update',i,patch},'Salvo');
const vndMv=(i,dir)=>vndOp({op:'move',i,dir});
const vndDel=i=>{if(confirm('Excluir este item do site?'))vndOp({op:'del',i},'Item excluído')};
function vndAdd(){const n=$('#np-n').value.trim();if(!n){toast('Informe o nome');return}vndOp({op:'add',item:{n,p:String($('#np-p').value||'0').replace(',','.')}},'Item adicionado')}
async function vndSt(id,st){if(st==='cancelado'&&!confirm('Cancelar este pedido? O estoque dos itens será devolvido e não dá para desfazer.'))return;try{await fx('/api/sales/status',{site:VS.site,id,st});toast('Pedido atualizado');await vndSite()}catch(e){toast(e.message==='cancelled'?'Pedido já cancelado':'Falha ao atualizar')}}
function vndCsv(){const q=v=>'"'+String(v==null?'':v).replace(/"/g,'""').replace(/^([=+\-@])/,"'$1")+'"';const rows=[['Pedido','Data','Cliente','WhatsApp','Itens','Subtotal','Desconto','Frete','Total','Tipo','Endereço','Pagamento','Status','Obs']].concat(vndFilter().map(o=>[o.no,new Date(o.at).toLocaleString('pt-BR'),o.name,o.tel,o.items.map(l=>l.q+'x '+l.n).join('; '),o.sub,o.d,o.fee,o.total,o.mode,o.addr,o.pay,STL[o.st],o.obs]));const u=URL.createObjectURL(new Blob(['﻿'+rows.map(r=>r.map(q).join(';')).join('\n')],{type:'text/csv'})),a=document.createElement('a');a.href=u;a.download='vendas.csv';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
