async function intMp(){const t=$('#i-mp').value.trim();if(!t){toast('Cole o token do Mercado Pago');return}try{await fx('/api/integrations/mp',{token:t});toast('Mercado Pago conectado');vndInteg()}catch(e){toast(e.message||'Falha ao conectar')}}
async function intMe(){try{await fx('/api/integrations/me',{token:$('#i-me').value.trim(),cep:$('#i-cep').value,w:$('#i-w').value,h:$('#i-h').value,l:$('#i-l').value,g:$('#i-g').value,svcs:$('#i-sv').value,sb:$('#i-sb').checked});toast('Melhor Envio salvo');vndInteg()}catch(e){toast(e.message||'Falha ao salvar')}}
async function intRm(w){if(!confirm('Desconectar? As lojas deixam de calcular frete / receber online até você conectar de novo.'))return;try{await fx('/api/integrations/remove',{which:w});toast('Desconectado');vndInteg()}catch(e){toast('Falha')}}
