function vndExp(){const rows=[DXH.join(';')].concat(VS.d.products.map(p=>[p.n,String(p.p).replace('.',','),p.c,p.d,p.v,p.s===''?'':p.s,p.w===''?'':p.w,p.o?'sim':'',p.e].map(dxCell).join(';')));dxSave(slug(VS.d.site.name)+'-produtos.csv','\ufeff'+rows.join('\r\n')+'\r\n','text/csv').then(ok=>ok&&toast('Planilha exportada'))}
