async function vndImp(f){if(!f)return;if(f.size>2e6){toast('Arquivo grande demais (máx. 2 MB)');return}try{const rows=dxParse(await f.text());if(rows.length<2){toast('Planilha vazia');return}const g=dxObjs(rows);if(g.err){toast(g.err);return}const m=(document.querySelector('input[name=vnm]:checked')||{}).value||'merge';const r=await fx('/api/sales/product',{site:VS.site,op:'import',mode:m,rows:g.objs.map(q=>{const o=Object.assign({},q);delete o.f;delete o.i;return o})});toast('✅ '+r.add+' novo(s), '+r.up+' atualizado(s)'+(r.lim?', '+r.lim+' acima do limite de 60':'')+'. Já vale no site.');await vndSite()}catch(e){toast(e.message==='empty'?'Nenhum produto válido na planilha':'Falha ao importar')}}
